#!/bin/bash
set -e
source preview15-work/env.sh
cd "$TASK_ROOT"
build(){ local src=$1; shift; cmake -S deps/$src -B build-$src -G Ninja -DCMAKE_BUILD_TYPE=Release -DCMAKE_C_FLAGS="$CFLAGS" -DCMAKE_CXX_FLAGS="$CXXFLAGS" -DCMAKE_INSTALL_PREFIX="$TASK_ROOT/prefix" -DCMAKE_PREFIX_PATH="$CMAKE_PREFIX_PATH" "$@" && cmake --build build-$src -j6 && cmake --install build-$src; }
build SDL-release-3.4.0 -DSDL_TESTS=OFF -DSDL_EXAMPLES=OFF -DSDL_WAYLAND=ON -DSDL_WAYLAND_SHARED=ON -DSDL_WAYLAND_LIBDECOR=ON -DSDL_WAYLAND_LIBDECOR_SHARED=ON -DSDL_PIPEWIRE=OFF -DSDL_PULSEAUDIO=ON -DSDL_JACK=OFF -DSDL_KMSDRM=OFF
build SDL_image-release-3.2.4 -DSDLIMAGE_VENDORED=OFF -DSDLIMAGE_BACKEND_STB=ON -DSDLIMAGE_PNG=ON -DSDLIMAGE_JPG=ON -DSDLIMAGE_AVIF=OFF -DSDLIMAGE_TIF=OFF -DSDLIMAGE_WEBP=OFF -DSDLIMAGE_JXL=OFF
build SDL_ttf-release-3.2.2 -DSDLTTF_VENDORED=OFF -DSDLTTF_HARFBUZZ=OFF -DSDLTTF_PLUTOSVG=OFF -DFREETYPE_LIBRARY_RELEASE="$TASK_ROOT/sysroot/usr/lib/x86_64-linux-gnu/libfreetype.so" -DSDLTTF_SAMPLES=OFF
build SDL_mixer-main -DSDLMIXER_VENDORED=OFF -DSDLMIXER_OPUS=OFF -DSDLMIXER_MIDI=OFF -DSDLMIXER_GME=OFF -DSDLMIXER_WAVPACK=OFF -DSDLMIXER_MOD=OFF -DSDLMIXER_FLAC=OFF -DSDLMIXER_MP3=OFF -DSDLMIXER_VORBIS_VORBISFILE=OFF -DSDLMIXER_VORBIS_STB=ON -DSDLMIXER_TESTS=OFF -DSDLMIXER_SAMPLES=OFF -DSDLMIXER_EXAMPLES=OFF
